function parseTopics(text){
  text=String(text||'');
  var lines=text.split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;});
  return lines.map(function(line){
    var m=line.match(/@(\d+)\s*$/);
    var mins=m? +m[1] : null;
    var topic=line.replace(/@\d+\s*$/,'').trim();
    return {topic:topic, mins:mins};
  });
}
function addMin(hhmm, mins){
  var p=String(hhmm).split(':'); var h=+p[0], m=+p[1];
  var t=(h*60+m)+mins; h=Math.floor(t/60)%24; m=((t%60)+60)%60;
  return (h<10?'0':'')+h+':'+(m<10?'0':'')+m;
}
function buildAgenda(title, duration, topics, startTime){
  duration=Math.round(+duration);
  if(isNaN(duration)||duration<=0) return {error:'会议时长须为正整数（分钟）'};
  startTime=startTime||'09:00';
  var list=parseTopics(topics);
  if(!list.length) return {error:'请至少填写一个议题'};
  var explicit=list.filter(function(t){return t.mins!=null;});
  var sum=explicit.reduce(function(a,t){return a+t.mins;},0);
  var remaining=duration - sum;
  var nulls=list.filter(function(t){return t.mins==null;});
  if(remaining<0) return {error:'议题指定时长累计 '+sum+' 分钟，已超过总时长 '+duration+' 分钟'};
  var perNull = nulls.length? Math.floor(remaining/nulls.length) : 0;
  var slots=[]; var cur=startTime;
  list.forEach(function(t){
    var mins = t.mins!=null? t.mins : perNull;
    var end=addMin(cur,mins);
    slots.push({start:cur, end:end, topic:t.topic, mins:mins});
    cur=end;
  });
  var notes='## 会议纪要 · '+title+'\n\n| 决议 | 负责人 | 截止 |\n|------|--------|------|\n| | | |\n\n### 行动项\n- [ ] \n';
  return {title:title, duration:duration, slots:slots, total:duration, notesTemplate:notes, over:false};
}
var EXPORTS={parseTopics:parseTopics, addMin:addMin, buildAgenda:buildAgenda};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MeetingAgendaForgePure = EXPORTS; }
